SELECT g.id, g.name_original, g.confidence_score, (SELECT count(*) FROM sources s WHERE s.entity_id=g.id) AS n_src FROM geo_entities g WHERE g.id IN (291, 366, 411, 459, 528, 591, 601, 607, 669, 887) ORDER BY g.id;
